import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
import {
	dotsSix,
	lock,
	pushPinSimple,
	pushPinSimpleFill,
} from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { type ColumnType } from "../dom-table/column.service";

export type ColumnSettingsItem = ColumnType & {
	/** If true, the column is pinnable; the pin icon will be enabled. */
	pinnable?: boolean;
	/** If true, the column is hideable; the checkbox will be displayed. */
	hideable?: boolean;
	/** If true, the column is reorderable; the grab icon will be enabled. */
	reorderable?: boolean;
};

const DEFAULT_I18N = {
	header: "Column settings",
	description: "Select or deselect to show or hide columns.",
	descriptionReorder: "Reorder columns by dragging.",
	descriptionPin: "Use the pin button to pin or unpin a column to the left.",
	tooltipPin: "This column can't be pinned.",
	tooltipUnpin: "This column can't be unpinned.",
	tooltipVisibility: "This column can't be hidden.",
	tooltipReorder: "This column can't be reordered.",
};
const TOOLTIP_DATA_ID = "column-settings-visibility-label";

export type ColumnSettingsChangeDetail =
	| {
			type: "reorder";
			columns: ColumnSettingsItem[];
			fromIdx: number;
			toIdx: number;
	  }
	| {
			type: "pin";
			column: ColumnSettingsItem;
			pinned: boolean;
			columns: ColumnSettingsItem[];
	  }
	| {
			type: "visibility";
			column: ColumnSettingsItem;
			visible: boolean;
			columns: ColumnSettingsItem[];
	  };

/**
 * @since 2.18.43
 * @status stable
 *
 * @slot header - Optional slot for the header section. If not provided, a default header with description will be shown.
 * @slot description - Optional slot for the description text, placed below the header. Only used if the header slot is not provided.
 * @slot column-[columnId] - Optional slot for the column content, where [columnId] is the `id` of the column.
 * @slot column-[columnId]-label - Optional slot for the column label, where [columnId] is the `id` of the column.
 * @slot column-[columnId]-suffix - Optional slot for additional content to be placed after the column label in the visibility control.
 * @slot tooltip-pin-[columnId] - Optional slot for custom tooltip content when hovering over a disabled pin button for a specific column.
 * @slot tooltip-visibility-[columnId] - Optional slot for custom tooltip content when hovering over a disabled visibility checkbox for a specific column.
 * @slot tooltip-reorder-[columnId] - Optional slot for custom tooltip content when hovering over a disabled reorder grab handle for a specific column.
 */
@Component({
	tag: "hbr-column-settings",
	styleUrl: "column-settings.scss",
	shadow: true,
})
export class ColumnSettings {
	/** The array of column configuration objects, the columns of the hbr-dom-table. */
	@Prop({ mutable: true }) columns: ColumnSettingsItem[] = [];

	/** When `true`, the pin icon column is shown and columns can be pinned to the left. */
	@Prop() pinnable?: boolean = false;

	/** When `true`, the grab icon is shown and columns can be reordered. */
	@Prop() reorderable?: boolean = false;

	/** Localization object for header, description, and tooltips */
	@Prop() i18n?: Partial<typeof DEFAULT_I18N> = { ...DEFAULT_I18N };

	/** An array of column IDs that is hidden visually. */
	@Prop() hidden: Array<string> = ["selectable", "expandable"];

	/**
	 * Emitted when columns are reordered, pinned/unpinned, or toggled visible/hidden.
	 * Check detail.type ("reorder" | "pin" | "visibility") to identify the action.
	 */
	@Event({ eventName: "hbr-columns-change" })
	hbrColumnsChange: EventEmitter<ColumnSettingsChangeDetail>;

	@Element() host: HTMLHbrColumnSettingsElement;
	@State() private _dragOverId: string | null = null;
	@State() private _insertAfter = false;
	private columnSettings!: HTMLDivElement;
	private _dragId: string | null = null;
	private dragStartEle: HTMLElement | undefined;

	componentDidRender() {
		this.orderedCols.forEach((col) => {
			if (
				this.reorderable &&
				!col.reorderable &&
				this[`tooltip-${col.id}`] instanceof HTMLElement
			) {
				if (this[`button-${col.id}`] instanceof HTMLElement) {
					this[`tooltip-${col.id}`].anchor = this[`button-${col.id}`];
				}
			}
		});
	}

	private get visibleCols(): ColumnSettingsItem[] {
		return this.columns.filter((c) => c.id !== "empty" && c.pin !== "right");
	}

	private get pinnedCols(): ColumnSettingsItem[] {
		return this.visibleCols.filter((c) => c.pin === "left");
	}

	private get orderedCols(): ColumnSettingsItem[] {
		const unpinned = this.visibleCols.filter((c) => c.pin !== "left");
		return [...this.pinnedCols, ...unpinned];
	}

	private get icons() {
		const custom = getBootstrapConfig()?.systemIcons;
		return {
			grab: custom?.["dots-six"] ?? dotsSix,
			lock: custom?.lock ?? lock,
			pin: custom?.["push-pin-simple"] ?? pushPinSimple,
			pinFill: custom?.["push-pin-simple-fill"] ?? pushPinSimpleFill,
		};
	}

	private normalizeColumns(columns: ColumnSettingsItem[]) {
		const pinnedLeftCols = columns.filter((c) => c.pin === "left");
		const unpinnedCols = columns.filter((c) => !c.pin && c.id !== "empty");
		const emptyCol = columns.find((c) => c.id === "empty");
		const pinnedRightCols = columns.filter((c) => c.pin === "right");

		return [
			...pinnedLeftCols,
			...unpinnedCols,
			...(emptyCol ? [emptyCol] : []),
			...pinnedRightCols,
		];
	}

	private handlePin(col: ColumnSettingsItem) {
		const nowPinned = col.pin !== "left";

		// Remove the column from its current position, then re-insert it at the
		// correct zone boundary so that:
		//   pinning   → appended after the last pinned column
		//   unpinning → prepended before the first unpinned column
		const without = this.columns.filter((c) => c.id !== col.id);
		const updatedCol = {
			...col,
			pin: nowPinned ? ("left" as const) : undefined,
		};

		let insertIdx: number;
		if (nowPinned) {
			// Find the index right after the last currently-pinned column
			const lastPinnedIdx = without.reduce(
				(acc, c, i) => (c.pin === "left" ? i : acc),
				-1,
			);
			insertIdx = lastPinnedIdx + 1;
		} else {
			// Find the index of the first currently-unpinned, non-special column
			const firstUnpinnedIdx = without.findIndex(
				(c) => c.pin !== "left" && c.id !== "empty",
			);
			insertIdx = firstUnpinnedIdx === -1 ? without.length : firstUnpinnedIdx;
		}

		const updated = this.normalizeColumns([
			...without.slice(0, insertIdx),
			updatedCol,
			...without.slice(insertIdx),
		]);
		this.hbrColumnsChange.emit({
			type: "pin",
			column: updatedCol,
			pinned: nowPinned,
			columns: updated,
		});
	}

	private handleVisibility(col: ColumnSettingsItem, visible: boolean) {
		const updated = this.normalizeColumns(
			this.columns.map((c) =>
				c.id === col.id ? { ...c, hidden: !visible } : c,
			),
		);
		this.hbrColumnsChange.emit({
			type: "visibility",
			column: { ...col, hidden: !visible },
			visible,
			columns: updated,
		});
	}

	private handleDragStart = (e: DragEvent, colId: string) => {
		this._dragId = colId;
		const ele = e.target as HTMLElement;
		this.dragStartEle = ele;
		ele?.classList.add("item-dragging--start");
		if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
	};

	private handleDragOver = (e: DragEvent, colId: string) => {
		e.preventDefault();
		// Block cross-zone drag: dragged item must be in the same zone as the target
		if (this._dragId) {
			const draggedCol = this.columns.find((c) => c.id === this._dragId);
			const targetCol = this.columns.find((c) => c.id === colId);
			if ((draggedCol?.pin === "left") !== (targetCol?.pin === "left")) {
				if (e.dataTransfer) e.dataTransfer.dropEffect = "none";
				this._dragOverId = null;
				return;
			}
		}
		if (this.dragStartEle) {
			this.dragStartEle.classList.remove("item-dragging--start");
		}
		this.columnSettings?.classList.add("dragging");
		if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
		const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
		this._insertAfter = e.clientY > rect.top + rect.height / 2;
		this._dragOverId = colId;
	};

	private handleDragLeave = (e: DragEvent) => {
		if (!(e.currentTarget as HTMLElement).contains(e.relatedTarget as Node)) {
			this._dragOverId = null;
		}
	};

	private handleDragEnd = () => {
		this._dragId = null;
		this._dragOverId = null;
		if (this.dragStartEle) {
			this.dragStartEle.classList.remove("item-dragging");
			this.dragStartEle.classList.remove("item-dragging--start");
			this.dragStartEle = undefined;
		}
		this.columnSettings?.classList.remove("dragging");
	};

	private handleDrop = (e: DragEvent, targetId: string) => {
		e.preventDefault();
		const dragId = this._dragId;
		const insertAfter = this._insertAfter;
		this._dragId = null;
		this._dragOverId = null;
		if (!dragId || dragId === targetId) return;

		const draggedCol = this.columns.find((c) => c.id === dragId);
		if (draggedCol?.reorderable === false) return;

		// Block cross-zone drops: pinned items stay in the pinned zone, unpinned in the unpinned zone
		const targetCol = this.columns.find((c) => c.id === targetId);
		if ((draggedCol?.pin === "left") !== (targetCol?.pin === "left")) return;

		const rightPinned = this.columns.filter((c) => c.pin === "right");
		const rightPinnedIds = new Set(rightPinned.map((c) => c.id));
		const draggable = this.columns.filter(
			(c) => c.id !== "empty" && !rightPinnedIds.has(c.id),
		);

		const orderedList = [
			...draggable.filter((c) => c.pin === "left"),
			...draggable.filter((c) => c.pin !== "left"),
		];

		const fromIdx = orderedList.findIndex((c) => c.id === dragId);
		const toIdx = orderedList.findIndex((c) => c.id === targetId);
		if (fromIdx === -1 || toIdx === -1) return;

		const [moved] = orderedList.splice(fromIdx, 1);
		const insertPos =
			orderedList.findIndex((c) => c.id === targetId) + (insertAfter ? 1 : 0);
		orderedList.splice(insertPos, 0, moved);

		const emptyCol = this.columns.find((c) => c.id === "empty");
		const result: ColumnSettingsItem[] = [
			...orderedList,
			...(emptyCol ? [emptyCol] : []),
			...rightPinned,
		];
		this.hbrColumnsChange.emit({
			type: "reorder",
			fromIdx,
			toIdx,
			columns: result,
		});
	};

	private cleanDrag = (event: MouseEvent) => {
		const ele = event.target as HTMLElement;
		ele.closest(".item")?.classList.remove("item-dragging");
	};

	private renderPinButton(col: ColumnSettingsItem) {
		if (!this.pinnable) return null;

		const { pin, pinFill } = this.icons;
		const isDisabled = !col.pinnable;

		if (isDisabled) {
			const tooltipText =
				col.pin === "left"
					? this.i18n?.tooltipUnpin ?? DEFAULT_I18N.tooltipUnpin
					: this.i18n?.tooltipPin ?? DEFAULT_I18N.tooltipPin;
			return (
				<hbr-tooltip hoist>
					<hbr-button variant="text" disabled>
						<hbr-icon
							asset={col.pin === "left" ? pinFill : pin}
							class="pin-icon--disabled"
						/>
					</hbr-button>
					<slot name={`tooltip-pin-${col.id}`} slot="content">
						{tooltipText}
					</slot>
				</hbr-tooltip>
			);
		}

		const isPinned = col.pin === "left";
		return (
			<hbr-button variant="text" onClick={() => this.handlePin(col)}>
				<hbr-icon
					asset={isPinned ? pinFill : pin}
					class={isPinned ? "pin-icon--pinned" : "pin-icon--unpinned"}
				/>
			</hbr-button>
		);
	}

	private renderVisibilityControl(
		col: ColumnSettingsItem,
		label: string | undefined,
	) {
		const slot = [
			<slot name={`column-${col.id}`}>
				<hbr-truncation tooltipTarget={`[data-id="${TOOLTIP_DATA_ID}"]`}>
					<slot name={`column-${col.id}-label`}>{label}</slot>
				</hbr-truncation>
			</slot>,
			<slot name={`column-${col.id}-suffix`} slot="element-suffix" />,
		];
		return (
			<div class="visibility-control">
				<slot name={`visibility-${col.id}`}>
					{col.hideable ? (
						<hbr-checkbox
							class="checkbox"
							checked={!col.hidden}
							value={col.id}
							onHbr-change={(e: CustomEvent) => {
								this.handleVisibility(
									col,
									(e.target as HTMLInputElement).checked,
								);
							}}
						>
							{slot}
						</hbr-checkbox>
					) : (
						<div class="locked">
							<hbr-tooltip hoist>
								<hbr-icon asset={this.icons.lock} />
								<slot name={`tooltip-visibility-${col.id}`} slot="content">
									{this.i18n?.tooltipVisibility ??
										DEFAULT_I18N.tooltipVisibility}
								</slot>
							</hbr-tooltip>
							<div class="locked-content">{slot}</div>
						</div>
					)}
				</slot>
			</div>
		);
	}

	private renderRow(
		col: ColumnSettingsItem,
		isDragOver = false,
		insertAfter = false,
		inert = {},
	) {
		const label = col.name;
		return (
			<div
				class={{
					hidden: this.hidden.includes(col.id),
				}}
				{...inert}
			>
				<div
					class={{
						row: true,
						"row--drop-after": isDragOver && insertAfter,
						"row--drop-before": isDragOver && !insertAfter,
					}}
				>
					{this.reorderable && (
						<hbr-button
							data-id={col.id}
							disabled={!col.reorderable}
							variant="text"
							class="grab-btn"
							ref={(ref) => {
								this[`button-${col.id}`] = ref;
							}}
							onMouseDown={(e) => {
								const ele = e.target as HTMLElement;
								ele.closest(".item")?.classList.add("item-dragging");
							}}
							onMouseUp={this.cleanDrag}
							onMouseLeave={this.cleanDrag}
						>
							<hbr-icon asset={this.icons.grab} class="icon" />
						</hbr-button>
					)}
					{this.pinnable && this.renderPinButton(col)}
					{this.renderVisibilityControl(col, label)}
				</div>
				{this.reorderable && !col.reorderable && (
					<hbr-portal>
						<hbr-tooltip
							hoist
							ref={(ref) => {
								this[`tooltip-${col.id}`] = ref;
							}}
							placement="left"
						>
							<slot name={`tooltip-reorder-${col.id}`} slot="content">
								{this.i18n?.tooltipReorder ?? DEFAULT_I18N.tooltipReorder}
							</slot>
						</hbr-tooltip>
					</hbr-portal>
				)}
			</div>
		);
	}

	render() {
		const pinnedCount = this.pinnedCols.length;
		const i18n = { ...DEFAULT_I18N, ...this.i18n };

		return (
			<Host>
				<div part="base" class="base">
					<slot name="header">
						<div part="header-wrapper" class="header">
							<hbr-text
								part="header"
								aria-level="3"
								type="primary"
								weight="semibold"
								size="sm"
							>
								{i18n.header}
							</hbr-text>
							<slot name="description">
								<hbr-text part="description" type="secondary" size="sm">
									{i18n.description}{" "}
									{this.reorderable && ` ${i18n.descriptionReorder}`}
									{this.pinnable && ` ${i18n.descriptionPin}`}
								</hbr-text>
							</slot>
						</div>
					</slot>
					<div
						role="list"
						class="column-settings"
						ref={(ref) => {
							this.columnSettings = ref;
						}}
					>
						{this.orderedCols.flatMap((col, idx) => {
							const showDivider =
								pinnedCount > 0 && col.pin !== "left" && idx === pinnedCount;
							const isDragOver = this._dragOverId === col.id;
							const inert = this.hidden.includes(col.id) ? { inert: true } : {};
							const row = this.renderRow(
								col,
								isDragOver,
								this._insertAfter,
								inert,
							);

							return [
								showDivider ? <hbr-divider class="divider" /> : null,
								!col.reorderable ? (
									row
								) : (
									<div
										role="listitem"
										key={col.id}
										class={{
											item: true,
											hidden: this.hidden.includes(col.id),
										}}
										data-id={`column-${col.id}`}
										draggable={true}
										onDragStart={(e: DragEvent) =>
											this.handleDragStart(e, col.id)
										}
										onDragOver={(e: DragEvent) =>
											this.handleDragOver(e, col.id)
										}
										onDragLeave={this.handleDragLeave}
										onDragEnd={this.handleDragEnd}
										onDrop={(e: DragEvent) => this.handleDrop(e, col.id)}
										{...inert}
									>
										<div class="indicator top-indicator" />
										{row}
										<div class="indicator bottom-indicator" />
									</div>
								),
							];
						})}
					</div>
				</div>
				<hbr-portal>
					<hbr-tooltip data-id={TOOLTIP_DATA_ID} />
				</hbr-portal>
			</Host>
		);
	}
}
